import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {[number,number,number]} position
 * @property {[number,number,number]} rotation
 * @property {[number,number,number]} scale
 * @property {{imageUrl:string}} assets
 * @property {{textContent:string}} textContent
 * @property {{colors?:Object}} colors
 * @property {Array} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {{load:(url:string)=>THREE.Texture}} textureLoader
 * @property {Object} fontAtlas
 * @property {Object.<string, Function>} primitives
 */

/**
 * Creates a pricing card label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
	// root container
	const root = new Group();

	// apply placement transforms
	const [px, py, pz] = config.position ?? [0, 0, 0];
	const [rx, ry, rz] = config.rotation ?? [0, 0, 0];
	const [sx, sy, sz] = config.scale ?? [1, 1, 1];
	root.position.set(px, py, pz);
	root.rotation.set(rx, ry, rz);
	root.scale.set(sx, sy, sz);

	/** ---------- Background Plane ---------- **/
	const bgTexture = ctx.textureLoader.load(config.assets?.imageUrl);
	const bgTexNode = texture(bgTexture);
	const bgMaterial = new MeshBasicNodeMaterial({ map: bgTexNode, transparent: true });
	const bgGeometry = new PlaneGeometry(1, 1);
	const bgMesh = new Mesh(bgGeometry, bgMaterial);

	// Preserve original aspect ratio (512 × 320) if known
	const imgAspect = bgTexture?.image?.width && bgTexture?.image?.height
		? bgTexture.image.width / bgTexture.image.height
		: 512 / 320;
	bgMesh.scale.set(imgAspect, 1, 1);
	root.add(bgMesh);

	/** ---------- Text Mesh (MSDF) ---------- **/
	const textStr = config.textContent?.[0] ?? 'Pricing 1';
	const textColor = (config.colors?.ink ?? '#16161d');
	const textMesh = createTextMesh({
		text: textStr,
		fontAtlas: ctx.fontAtlas,
		// headline scale approximated from design tokens (0.34 scene‑units)
		size: 0.34,
		color: textColor,
		// position slightly in front of the background to avoid z‑fighting
		position: [0, 0, 0.001],
		// centre the text
		anchor: 'center',
		// use the supplied atlas region (0,0,512,320) – the utility can accept it if needed
		atlasRegion: { x: 0, y: 0, width: 512, height: 320 },
	});
	root.add(textMesh);

	/** ---------- Event Handlers (none in spec) ---------- **/
	root.userData.handlers = {};

	/** ---------- Cleanup ---------- **/
	root.userData.cleanup = () => {
		// dispose background resources
		bgGeometry.dispose();
		bgMaterial.dispose();
		// texture is cached; dispose only if you own it explicitly
		// dispose text resources
		if (textMesh) {
			if (textMesh.geometry) textMesh.geometry.dispose();
			if (textMesh.material) {
				// Materials created by createTextMesh may be arrays (e.g., for multi‑material)
				if (Array.isArray(textMesh.material)) {
					textMesh.material.forEach((m) => m.dispose());
				} else {
					textMesh.material.dispose();
				}
			}
		}
		// kill any GSAP timelines that might have been created (none for this node)
		gsap.globalTimeline.clear();
	};

	// apply cinematic primitives if any (none for this node)
	if (Array.isArray(config.cinematicPrimitives) && config.cinematicPrimitives.length) {
		config.cinematicPrimitives.forEach((p) => {
			const fn = ctx.primitives[p.name];
			if (typeof fn === 'function') {
				fn(root, p.params);
			}
		});
	}

	return root;
}
